phase1.code:
fn main() {
    // ---- Mutable references allow modification ----
    let mut s = String::from("hello");
    change(&mut s);
    println!("s: {}", s);

    // ---- Only one mutable reference at a time ----
    let mut s2 = String::from("hello");
    let r1 = &mut s2;
    // let r2 = &mut s2;  // ERROR! Cannot borrow as mutable more than once
    // println!("r1: {}, r2: {}", r1, r2);

    // ---- Mutable references and immutable references cannot coexist ----
    let mut s3 = String::from("hello");
    let r3 = &s3;
    // let r4 = &mut s3;  // ERROR! Cannot borrow as mutable while immutable borrow exists
    println!("r3: {}", r3);
    // r3 is dropped here
    let r4 = &mut s3;  // Now we can borrow mutably
    println!("r4: {}", r4);

    // ---- Scoping allows multiple mutable references ----
    let mut s4 = String::from("hello");
    {
        let r5 = &mut s4;
        r5.push_str(" world");
    }  // r5 goes out of scope
    let r6 = &mut s4;  // New mutable reference is allowed
    r6.push_str("!");
    println!("s4: {}", s4);

    // ---- Mutable references to different data ----
    let mut s5 = String::from("hello");
    let mut s6 = String::from("world");
    let r7 = &mut s5;
    let r8 = &mut s6;  // Allowed: different data
    println!("r7: {}, r8: {}", r7, r8);

    // ---- Function with mutable reference ----
    let mut s7 = String::from("hello");
    modify_string(&mut s7);
    println!("s7: {}", s7);
}

fn change(s: &mut String) {
    s.push_str(", world");
}

fn modify_string(s: &mut String) {
    s.push_str("!!!");
}

